-- ----------------------------
-- View structure for vw_alarmason
-- ----------------------------
DROP VIEW IF EXISTS `vw_alarmason`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_alarmason` AS select `segmento`.`Puerto` AS `Puerto`,`segmento`.`Dispositivo` AS `Dispositivo`,`segmento`.`Bloque` AS `Bloque`,`segmento`.`Nombre` AS `Nombre`,`segmento`.`Descripcion` AS `Descripcion`,`segmento`.`Grupo` AS `Grupo`,`segmento`.`Orden` AS `Orden`,`segmento`.`Escala1` AS `Escala1`,`segmento`.`Escala2` AS `Escala2`,`segmento`.`Status` AS `Status`,`segmento`.`Min` AS `Min`,`segmento`.`Max` AS `Max`,`segmento`.`Alarma1` AS `Alarma1`,`segmento`.`Alarma2` AS `Alarma2`,`segmento`.`Inicio` AS `Inicio`,`segmento`.`Largo` AS `Largo`,`segmento`.`TiempoReal` AS `TiempoReal`,`segmento`.`AlarmaStatus` AS `AlarmaStatus`,`segmento`.`Tipo` AS `Tipo`,`segmento`.`Historico` AS `Historico`,`segmento`.`Decimales` AS `Decimales`,`segmento`.`Factor` AS `Factor`,`segmento`.`TipoDato` AS `TipoDato` from `segmento`;


DROP VIEW IF EXISTS `vreportealarmas`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vreportealarmas` AS select `al`.`Puerto` AS `puerto`,(_utf8'Id' = `al`.`Dispositivo`) AS `id`,(_utf8'Dispositivo' = `dp`.`Nombre`) AS `Dispositivo`,`al`.`Nombre` AS `Nombre`,`al`.`Alarma1` AS `Alarma1`,`al`.`Alarma2` AS `Alarma2`,`lo`.`Valor` AS `valor`,`lo`.`fecha` AS `fecha` from ((`vw_alarmason` `al` join `dispositivo` `dp`) join `alarmalog` `lo`) where ((`al`.`Dispositivo` = `dp`.`Dispositivo`) and (`al`.`AlarmaStatus` = 1) and (`al`.`Dispositivo` = `lo`.`Dispositivo`) and (`al`.`Nombre` = `lo`.`Nombre`));

-- ----------------------------
-- View structure for vreportealarmasold
-- ----------------------------
DROP VIEW IF EXISTS `vreportealarmasold`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vreportealarmasold` AS select `al`.`Puerto` AS `puerto`,(_utf8'Id' = `al`.`Dispositivo`) AS `'Id'= al.Dispositivo`,(_utf8'Dispositivo' = `dp`.`Nombre`) AS `'Dispositivo'= dp.Nombre`,`al`.`Nombre` AS `Nombre`,`al`.`Alarma1` AS `Alarma1`,`al`.`Alarma2` AS `Alarma2`,`lo`.`Valor` AS `valor`,`lo`.`fecha` AS `fecha` from ((`vw_alarmason` `al` join `dispositivo` `dp`) join `alarmalog` `lo`) where ((`al`.`Puerto` = `dp`.`Puerto`) and (`al`.`Dispositivo` = `dp`.`Dispositivo`) and (`al`.`AlarmaStatus` = 1) and (`lo`.`Puerto` = `dp`.`Puerto`) and (`al`.`Dispositivo` = `lo`.`Dispositivo`) and (`al`.`Nombre` = `lo`.`Nombre`));

-- ----------------------------
-- View structure for vreporteold2
-- ----------------------------
DROP VIEW IF EXISTS `vreporteold2`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vreporteold2` AS select `al`.`Puerto` AS `puerto`,(_utf8'Id' = `al`.`Dispositivo`) AS `id`,(_utf8'Dispositivo' = `dp`.`Nombre`) AS `Dispositivo`,`al`.`Nombre` AS `Nombre`,`al`.`Alarma1` AS `Alarma1`,`al`.`Alarma2` AS `Alarma2`,`lo`.`Valor` AS `valor`,`lo`.`fecha` AS `fecha` from ((`vw_alarmason` `al` join `dispositivo` `dp`) join `alarmalog` `lo`) where ((`al`.`Puerto` = `dp`.`Puerto`) and (`al`.`Dispositivo` = `dp`.`Dispositivo`) and (`al`.`AlarmaStatus` = 1) and (`lo`.`Puerto` = `dp`.`Puerto`) and (`al`.`Dispositivo` = `lo`.`Dispositivo`) and (`al`.`Nombre` = `lo`.`Nombre`));


