drop procedure if exists simpleproc;

CREATE PROCEDURE simpleproc ( FechaI date, FechaF date)
BEGIN
 

 drop temporary table if exists ReporteConsumo;
-- CREATE TEMPORARY TABLE ReporteConsumo 

select  ds.Clave , min(l1.fecha) as FechaInicio ,max(l2.fecha)  as FechaFin,0 as Minimo,0 as Maximo

,CONV( right(left(l1.cadena,14),8),16,10) ,  CONV( right(left(l2.cadena,14),8),16,10)

from dispositivo ds , lectura l1, lectura l2

where 
 ds.tipodispositivo = '452' 
and ds.status = 'On'  

and ds.clave = l1.dispositivo  
and ds.clave = l2.dispositivo

and l1.fecha >FechaI
and l2.fecha <FechaF

group by ds.clave;


 drop temporary table if exists ReporteConsumofinal;
CREATE TEMPORARY TABLE ReporteConsumoFinal 
select rp.clave ,rp.fechainicio, rp.fechafin, l1.cadena as c1, CONV( right(left(l1.cadena,14),8),16,10) As LecturaInicial,l2.cadena  as c2,  CONV( right(left(l2.cadena,14),8),16,10) as LecturaFinal from reporteconsumo rp , lectura l1, lectura l2
where rp.clave = l1.dispositivo 
and rp.fechaInicio = l1.fecha

and rp.clave = l2.dispositivo 
and rp.fechafin = l2.fecha;

end;

